fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            let diff = b - a;
            if diff == 0 {
                0
            } else if diff > 0 {
                // Need a positive net increase: odd increments only.
                // If diff is odd → 1 move; if even → 2 moves.
                if diff % 2 != 0 { 1 } else { 2 }
            } else {
                // diff < 0: need a net decrease by |diff|.
                // Can only subtract even in one move.
                // If |diff| is even → 1 move; if odd → 2 moves.
                if diff % 2 == 0 { 1 } else { 2 }
            }
        })
        .collect()
}

